import math

def check_n(n):
    """Checks if for all k such that gcd(k, n) = 1 and 1 <= k < n, k^2 - 1 is a multiple of n."""
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            if (k**2 - 1) % n != 0:
                return False
    return True

valid_n = []
for n in range(2, 16):
    if check_n(n):
        valid_n.append(n)

print(f"Valid integers n from 2 to 15: {valid_n}")
